    const capT = targets[1].h;   // высота заглавной в «СПбГУП» (по П)

    // ---------- раскладка «после сжатия» (стадия A): оставшиеся буквы каждой строки встают вплотную по центру ----------
    const GAP = 1.6, CX = vx + vw / 2;
