/* Золотой салют для первого экрана «100 лет СПбГУП».
   Ракеты вылетают из-за левого и правого края экрана, по баллистической дуге долетают к центру
   и раскрываются. Типы залпов: «пион», «золотая ива» (камуро), «кольцо», «кроссет» (звёзды делятся),
   «мерцающая корона» (искры с блёстками). Рисуется на <canvas> с учётом плотности пикселей экрана,
   свечение — заранее отрисованными мягкими спрайтами (без размытия и «пикселей»), хвосты — гладкими линиями.

   const fx = new GoldFireworks(canvas, { getSize: () => ({ w, h }) });
   fx.setIntensity(0..1)  — 0 = салют затухает и останавливается, 1 = полная программа
*/
(function (root) {
  const TAU = Math.PI * 2;
  const rnd = (a, b) => a + Math.random() * (b - a);
  const pick = a => a[(Math.random() * a.length) | 0];
  // палитра: от белого золота к тёплой бронзе (в RGB для смешивания)
  const PAL = {
    white: [255, 246, 224], champagne: [247, 226, 178], gold: [236, 196, 120],
    honey: [222, 170, 88], bronze: [196, 138, 66]
  };
  const SETS = [
    ['white', 'champagne', 'gold'], ['champagne', 'gold', 'honey'], ['gold', 'honey', 'bronze'], ['white', 'gold']
  ];

  function sprite(size, stops) {
    const c = document.createElement('canvas'); c.width = c.height = size;
    const g = c.getContext('2d'), r = size / 2, gr = g.createRadialGradient(r, r, 0, r, r, r);
    stops.forEach(([o, col]) => gr.addColorStop(o, col));
    g.fillStyle = gr; g.fillRect(0, 0, size, size); return c;
  }
  // мягкие спрайты свечения под каждый цвет
  const GLOW = {}, CORE = sprite(64, [[0, 'rgba(255,255,255,1)'], [0.25, 'rgba(255,250,235,.9)'], [0.6, 'rgba(255,240,210,.25)'], [1, 'rgba(255,240,210,0)']]);
  Object.keys(PAL).forEach(k => {
    const [r, g, b] = PAL[k];
    GLOW[k] = sprite(64, [[0, `rgba(${r},${g},${b},.95)`], [0.18, `rgba(${r},${g},${b},.55)`], [0.5, `rgba(${r},${g},${b},.14)`], [1, `rgba(${r},${g},${b},0)`]]);
  });
  const FLASH = sprite(256, [[0, 'rgba(255,226,170,.55)'], [0.3, 'rgba(240,190,110,.22)'], [1, 'rgba(240,190,110,0)']]);

  function GoldFireworks(canvas, opts) {
    const ctx = canvas.getContext('2d');
    let W = 0, H = 0, dpr = 1;
    let stars = [], rockets = [], sparks = [], flashes = [];
    let running = false, last = 0, intensity = 1, clock = 0, nextShow = 0.15, salvo = 0;

    function resize() {
      const s = opts.getSize(); W = s.w; H = s.h;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
      canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    // ---------- ракета: дуга от края к точке разрыва ----------
    function launch(side, tx, ty, type, delay) {
      const fromLeft = side < 0;
      const x0 = fromLeft ? -rnd(10, 30) : W + rnd(10, 30), y0 = H * rnd(0.62, 0.95);
      const T = rnd(0.95, 1.25), g = 260;
      rockets.push({ x: x0, y: y0, vx: (tx - x0) / T, vy: (ty - y0 - 0.5 * g * T * T) / T, g, t: -(delay || 0), T, type, set: pick(SETS), px: x0, py: y0, trail: [] });
    }

    // ---------- звезда ----------
    function star(x, y, vx, vy, o) {
      stars.push(Object.assign({ x, y, vx, vy, px: x, py: y, age: 0, life: 1.3, drag: 1.7, g: 150, size: 1.6, col: 'gold', hist: [], tail: 6, glitter: 0, ember: 0, split: 0, strobe: 0 }, o));
    }

    function burst(r) {
      const x = r.x, y = r.y, set = r.set;
      flashes.push({ x, y, age: 0, life: 0.6, size: rnd(280, 360) });
      const k = Math.min(W, 420) / 375;                         // масштаб под ширину экрана
      const type = r.type;
      if (type === 'willow') {                                    // золотая ива: длинные свисающие нити
        const n = 90; for (let i = 0; i < n; i++) { const a = i / n * TAU + rnd(-.04, .04), v = rnd(200, 260) * k;
          star(x, y, Math.cos(a) * v, Math.sin(a) * v, { life: rnd(2.6, 3.3), drag: 2.3, g: 70, col: pick(['gold', 'honey']), tail: 10, ember: 1, size: 1.4 }); }
      } else if (type === 'ring') {                               // кольцо с наклоном + сердцевина
        const n = 64, tilt = rnd(0.35, 0.75), rot = rnd(0, TAU), v = rnd(260, 300) * k;
        for (let i = 0; i < n; i++) { const a = i / n * TAU, ex = Math.cos(a) * v, ey = Math.sin(a) * v * tilt;
          star(x, y, ex * Math.cos(rot) - ey * Math.sin(rot), ex * Math.sin(rot) + ey * Math.cos(rot), { life: rnd(1.3, 1.6), col: pick(set), tail: 7 }); }
        for (let i = 0; i < 18; i++) { const a = rnd(0, TAU), vv = rnd(30, 90) * k; star(x, y, Math.cos(a) * vv, Math.sin(a) * vv, { life: rnd(.9, 1.2), col: 'white', size: 1.3, glitter: 1 }); }
      } else if (type === 'crossette') {                          // кроссет: звёзды делятся на четыре
        const n = 16; for (let i = 0; i < n; i++) { const a = i / n * TAU + rnd(-.05, .05), v = rnd(200, 240) * k;
          star(x, y, Math.cos(a) * v, Math.sin(a) * v, { life: rnd(.55, .7), col: 'champagne', size: 1.9, tail: 6, split: 1 }); }
      } else if (type === 'crown') {                              // мерцающая корона: пион с блёстками на излёте
        const n = 120; for (let i = 0; i < n; i++) { const a = rnd(0, TAU), v = Math.sqrt(Math.random()) * rnd(280, 340) * k;
          star(x, y, Math.cos(a) * v, Math.sin(a) * v, { life: rnd(1.4, 1.9), drag: 1.9, col: pick(set), glitter: 1, tail: 5 }); }
      } else {                                                    // пион: плотная сфера звёзд
        const n = 130; for (let i = 0; i < n; i++) {
          const u = rnd(-1, 1), th = rnd(0, TAU), s = Math.sqrt(1 - u * u), v = rnd(290, 360) * k;   // равномерно по сфере → объём
          star(x, y, Math.cos(th) * s * v, (u * 0.9 + Math.sin(th) * s * 0.4) * v, { life: rnd(1.1, 1.5), col: pick(set), tail: 7 }); }
        for (let i = 0; i < 24; i++) { const a = rnd(0, TAU), v = rnd(60, 130) * k; star(x, y, Math.cos(a) * v, Math.sin(a) * v, { life: rnd(.8, 1.1), col: 'white', size: 1.2, strobe: 1 }); }
      }
    }

    // ---------- программа салюта: залпы парами слева и справа, иногда финальный каскад ----------
    function program(dt) {
      if (intensity <= 0.02) return;
      clock += dt;
      if (clock < nextShow) return;
      salvo++;
      const types = ['peony', 'willow', 'ring', 'crown', 'crossette', 'peony'];
      const cx = W / 2, top = H * 0.16, mid = H * 0.38;
      if (salvo % 6 === 0) {                                      // каскад: 3 пары подряд
        for (let i = 0; i < 3; i++) {
          launch(-1, cx - W * rnd(.08, .22), rnd(top, mid), pick(types), i * 0.28);
          launch(1, cx + W * rnd(.08, .22), rnd(top, mid), pick(types), i * 0.28 + 0.14);
        }
        nextShow = clock + 3.4;
      } else {
        const t = pick(types), side = salvo % 2 ? -1 : 1;
        launch(side, cx + side * W * rnd(.02, .16), rnd(top, mid), t, 0);
        if (Math.random() < 0.55) launch(-side, cx - side * W * rnd(.06, .2), rnd(top, mid), t === 'willow' ? 'crown' : pick(types), rnd(.18, .4));
        nextShow = clock + rnd(1.1, 1.7);
      }
    }

    function step(dt) {
      program(dt);
      // ракеты
      for (let i = rockets.length - 1; i >= 0; i--) {
        const r = rockets[i]; r.t += dt; if (r.t < 0) continue;
        r.px = r.x; r.py = r.y; r.vy += r.g * dt; r.x += r.vx * dt; r.y += r.vy * dt;
        r.trail.push([r.x, r.y]); if (r.trail.length > 14) r.trail.shift();
        if (Math.random() < 0.9) sparks.push({ x: r.x, y: r.y, vx: -r.vx * 0.08 + rnd(-25, 25), vy: -r.vy * 0.08 + rnd(-10, 30), age: 0, life: rnd(.35, .7), col: pick(['gold', 'honey', 'champagne']), size: rnd(.7, 1.2) });
        if (r.t >= r.T) { burst(r); rockets.splice(i, 1); }
      }
      // звёзды
      for (let i = stars.length - 1; i >= 0; i--) {
        const s = stars[i]; s.age += dt;
        const f = Math.exp(-s.drag * dt); s.vx *= f; s.vy = s.vy * f + s.g * dt;
        s.px = s.x; s.py = s.y; s.x += s.vx * dt; s.y += s.vy * dt;
        s.hist.push(s.x, s.y); if (s.hist.length > s.tail * 2) s.hist.splice(0, 2);
        if (s.ember && Math.random() < 0.5) sparks.push({ x: s.x, y: s.y, vx: rnd(-6, 6), vy: rnd(10, 30), age: 0, life: rnd(.6, 1.2), col: 'honey', size: rnd(.6, 1) });
        if (s.glitter && s.age > s.life * 0.55 && Math.random() < 0.35) sparks.push({ x: s.x + rnd(-2, 2), y: s.y + rnd(-2, 2), vx: rnd(-10, 10), vy: rnd(0, 20), age: 0, life: rnd(.12, .3), col: 'white', size: rnd(.8, 1.3), twinkle: 1 });
        if (s.age >= s.life) {
          if (s.split) for (let j = 0; j < 4; j++) { const a = j / 4 * TAU + Math.atan2(s.vy, s.vx) + Math.PI / 4, v = rnd(90, 120);
            star(s.x, s.y, Math.cos(a) * v + s.vx * .3, Math.sin(a) * v + s.vy * .3, { life: rnd(.8, 1.1), col: 'gold', size: 1.3, tail: 5, glitter: 1 }); }
          stars.splice(i, 1);
        }
      }
      for (let i = sparks.length - 1; i >= 0; i--) { const p = sparks[i]; p.age += dt; if (p.age >= p.life) { sparks.splice(i, 1); continue; } p.vy += 60 * dt; p.x += p.vx * dt; p.y += p.vy * dt; }
      for (let i = flashes.length - 1; i >= 0; i--) { const fl = flashes[i]; fl.age += dt; if (fl.age >= fl.life) flashes.splice(i, 1); }
      // предохранитель от перегрузки слабых телефонов
      if (stars.length > 1400) stars.splice(0, stars.length - 1400);
      if (sparks.length > 1600) sparks.splice(0, sparks.length - 1600);
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      ctx.globalCompositeOperation = 'lighter';
      const I = intensity;
      const ex = opts.getExclude ? opts.getExclude() : null;   // область логотипа: салют там приглушён, логотип остаётся белым
      const dim = (x, y) => ex && x > ex[0] && x < ex[2] && y > ex[1] && y < ex[3] ? 0.2 : 1;
      // вспышки: тёплая подсветка неба в момент разрыва
      flashes.forEach(fl => { const t = fl.age / fl.life, a = (1 - t) * (1 - t) * I * dim(fl.x, fl.y), s = fl.size * (0.7 + 0.3 * t);
        ctx.globalAlpha = a; ctx.drawImage(FLASH, fl.x - s / 2, fl.y - s / 2, s, s); });
      // ракеты: тонкий светящийся след и яркая головка
      ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      rockets.forEach(r => { if (r.t < 0 || r.trail.length < 2) return;
        for (let j = 1; j < r.trail.length; j++) { const k = j / r.trail.length;
          ctx.globalAlpha = k * 0.75 * I; ctx.strokeStyle = 'rgb(247,226,178)'; ctx.lineWidth = 0.6 + k * 1.6;
          ctx.beginPath(); ctx.moveTo(r.trail[j - 1][0], r.trail[j - 1][1]); ctx.lineTo(r.trail[j][0], r.trail[j][1]); ctx.stroke(); }
        ctx.globalAlpha = I; ctx.drawImage(CORE, r.x - 7, r.y - 7, 14, 14); });
      // звёзды: гладкий хвост + свечение + ядро
      stars.forEach(s => {
        const t = s.age / s.life, fade = t < 0.7 ? 1 : 1 - (t - 0.7) / 0.3;
        let a = fade * I * dim(s.x, s.y); if (s.strobe) a *= (Math.sin(s.age * 38) > 0 ? 1 : 0.15);
        const [r, g, b] = PAL[s.col], h = s.hist, n = h.length / 2;
        for (let j = 1; j < n; j++) { const k = j / n;
          ctx.globalAlpha = a * k * 0.7; ctx.strokeStyle = `rgb(${r},${g},${b})`; ctx.lineWidth = s.size * (0.4 + k * 0.9);
          ctx.beginPath(); ctx.moveTo(h[j * 2 - 2], h[j * 2 - 1]); ctx.lineTo(h[j * 2], h[j * 2 + 1]); ctx.stroke(); }
        const tw = 0.85 + 0.15 * Math.sin(s.age * 24 + s.x);
        const gs = s.size * 10 * (1 - t * 0.35) * tw;
        ctx.globalAlpha = a * 0.85; ctx.drawImage(GLOW[s.col], s.x - gs / 2, s.y - gs / 2, gs, gs);
        const cs = s.size * 2.9 * tw; ctx.globalAlpha = a; ctx.drawImage(CORE, s.x - cs / 2, s.y - cs / 2, cs, cs);
      });
      // искры, угольки и блёстки
      sparks.forEach(p => { const t = p.age / p.life; let a = (1 - t) * I * dim(p.x, p.y); if (p.twinkle) a *= 0.5 + 0.5 * Math.sin(p.age * 60);
        const s = p.size * 4; ctx.globalAlpha = a; ctx.drawImage(p.twinkle ? CORE : GLOW[p.col], p.x - s / 2, p.y - s / 2, s, s); });
      ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    }

    function loop(now) {
      if (!running) return;
      const dt = Math.min(1 / 30, (now - (last || now)) / 1000); last = now;
      if (dt > 0) step(dt);
      draw();
      if (intensity <= 0.02 && !rockets.length && !stars.length && !sparks.length) { running = false; ctx.clearRect(0, 0, W, H); return; }
      requestAnimationFrame(loop);
    }

    this.resize = resize;
    this.setIntensity = v => { intensity = v; if (v > 0.02 && !running && document.visibilityState !== 'hidden') { running = true; last = 0; requestAnimationFrame(loop); } };
    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') running = false; else this.setIntensity(intensity); });
    resize();
  }
  root.GoldFireworks = GoldFireworks;
})(window);
